arguments.command:
python3 -I -c "
import json
d = json.load(open('measurements.json'))
def show(o, indent=0, maxlist=6):
    pad = '  '*indent
    if isinstance(o, dict):
        for k, v in o.items():
            if isinstance(v, (dict, list)):
                print(pad + str(k) + ':')
                show(v, indent+1)
            else:
                print(pad + str(k) + ': ' + repr(v))
    elif isinstance(o, list):
        print(pad + f'[list len={len(o)}]', end=' ')
        if len(o) and isinstance(o[0], (dict, list)):
            print()
            for i, x in enumerate(o[:3]):
                print(pad + f'- item {i}:')
                show(x, indent+2)
            if len(o) > 3: print(pad + '  ...')
        else:
            print(repr(o[:maxlist]) + (' ...' if len(o) > maxlist else ''))
show(d)
"

