python3 -I - <<'EOF'
import json, numpy as np
d = json.load(open('/app/measurements.json'))
sts = d['measurements'][0]
S = {s['panel']:(np.array(s['bias']), np.array(s['dI_dV'])) for s in sts['spectra']}
def integ(b,g,lo,hi,bg):
    m=(b>=lo)&(b<=hi); return np.trapz(np.clip(g[m]-bg,0,None), b[m])
# panel a
b,g=S['a']; 
for bg in [0.0,0.05,0.1]:
    L=integ(b,g,-8.6,-3.6,bg); U=integ(b,g,3.6,8.6,bg); print(f"a bg={bg}: lower={L:.3f} upper={U:.3f} ratio L/U={L/U:.3f}  L/(L+U)={L/(L+U):.3f}")
b,g=S['b']
for bg in [0.0,0.05,0.08]:
    L=integ(b,g,-7.0,-2.3,bg); U=integ(b,g,2.3,7.0,bg); print(f"b bg={bg}: lower={L:.3f} upper={U:.3f} ratio L/U={L/U:.3f}  L/(L+U)={L/(L+U):.3f}")
b,g=S['c']
for bg in [0.0,0.05,0.07]:
    L=integ(b,g,-4.0,-1.6,bg); U=integ(b,g,1.6,5.8,bg); print(f"c bg={bg}: lower={L:.3f} upper={U:.3f} ratio L/U={L/U:.3f}  L/(L+U)={L/(L+U):.3f}")
b,g=S['d']
for bg in [0.0,0.05]:
    L=integ(b,g,-4.4,0,bg); U=integ(b,g,0,4.4,bg); print(f"d bg={bg}: below mu={L:.3f} above={U:.3f} ratio={L/U:.3f}  L/(L+U)={L/(L+U):.3f}")
EOF

